import java.util.*;
import java.util.concurrent.*;
import static com.library.catalogattributes.CatalogAttributeSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:catalog-publication;DB_CLOSE_DELAY=-1;MODE=MYSQL","mybatis-plus.configuration.log-impl=org.apache.ibatis.logging.nologging.NoLoggingImpl"})
@AutoConfigureMockMvc
@ActiveProfiles("test")
public class PublicationServiceTest {
    @Autowired protected PublicationService service;
    @Autowired protected JdbcTemplate jdbc;
    @Autowired protected IntakeCatalog intake;
    @Autowired protected BookService books;
    @Autowired protected PlatformTransactionManager transactions;
    @Autowired protected MockMvc mvc;
    @Autowired protected com.fasterxml.jackson.databind.ObjectMapper applicationJson;
    protected final PublicationSupport.Actor admin=new PublicationSupport.Actor(821001,true,false),clerk=new PublicationSupport.Actor(821002,false,true),other=new PublicationSupport.Actor(821003,true,false),reader=new PublicationSupport.Actor(821004,false,false);
    protected UsernamePasswordAuthenticationToken auth(PublicationSupport.Actor a){return new UsernamePasswordAuthenticationToken(a.id(),"synthetic",List.of(new SimpleGrantedAuthority(a.admin()?"ROLE_ADMIN":a.librarian()?"ROLE_LIBRARIAN":"ROLE_READER")));}
    @BeforeEach protected void authenticate(){SecurityContextHolder.getContext().setAuthentication(auth(admin));}
    @AfterEach protected void clear(){SecurityContextHolder.clearContext();}
    protected long book(){long category=insert(jdbc,"INSERT INTO book_category(name) VALUES (?)","合成出版分类"+UUID.randomUUID());return insert(jdbc,"INSERT INTO book(isbn,title,publisher,category_id,price,stock_total,stock_available) VALUES (?,?,?,?,12.34,0,0)",UUID.randomUUID().toString().replace("-","").substring(0,20),"合成出版书目📚"+UUID.randomUUID(),"保值登记出版社",category);}
    protected ObjectNode changes(){return obj("publishDate",null,"pages",null,"description",null);}
    protected ObjectNode set(String f,Object value){return changes().set(f,obj("action","SET","value",value));}
    protected ObjectNode entry(long id,ObjectNode changes){JsonNode b=service.book(id,admin).path("book");return obj("bookId",id,"expectedRevision",b.get("revision"),"expectedMetadataDigest",b.get("metadataDigest"),"changes",changes,"evidence",obj("kind","COPYRIGHT_PAGE","reference","合成版权页，人工查阅填写"));}
    protected ObjectNode input(JsonNode...entries){return obj("operationKey",UUID.randomUUID().toString(),"mode","MANUAL","reason","馆员/管理员填写的依据，合成验证","entries",Arrays.asList(entries));}
    protected JsonNode preview(long id,ObjectNode changes){return service.preview(input(entry(id,changes)),admin);}
    protected JsonNode confirm(JsonNode p){return service.confirm(p.path("requestId").asLong(),obj("operationKey",p.get("operationKey"),"previewDigest",p.get("previewDigest")),admin);}
    protected void reason(String code,Runnable run){PublicationSupport.Failure e=assertThrows(PublicationSupport.Failure.class,run::run);assertEquals(code,e.code);}
    protected JsonNode http(org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder r,JsonNode body,PublicationSupport.Actor a,int status)throws Exception{if(body!=null)r.contentType("application/json").content(write(body));r.with(a==null?anonymous():authentication(auth(a)));var response=mvc.perform(r).andReturn().getResponse();assertEquals(status,response.getStatus(),response.getContentAsString());authenticate();return JSON.readTree(response.getContentAsString());}
    @Test void permissionsOwnershipAndBatchRolesAreEnforcedBeforeObjects()throws Exception{for(var actor:List.of(reader))assertEquals("CATALOG_PUBLICATION_ROLE_REQUIRED",http(get("/catalog-publications/books/99999999"),null,actor,403).path("data").path("reasonCode").asText());http(get("/catalog-publications/books/99999999"),null,null,403);long b=book(),c=book();ObjectNode n=input(entry(b,set("pages",0)));JsonNode p=service.preview(n,clerk);reason("OWNER_REQUIRED",()->service.getRequest(p.path("requestId").asLong(),admin));reason("OWNER_REQUIRED",()->service.getByKey(p.path("operationKey").asText(),other));reason("CATALOG_PUBLICATION_ROLE_REQUIRED",()->service.preview(input(entry(b,set("pages",0)),entry(c,set("pages",0))),clerk));assertTrue(service.book(b,clerk).has("book"));assertEquals("REQUEST_NOT_FOUND",http(get("/catalog-publications/999999999"),null,admin,404).path("data").path("reasonCode").asText());}
    @Test void nullEmptyZeroAndUnicodeHaveDistinctPersistentReceipts(){long b=book();ObjectNode c=changes();c.set("publishDate",obj("action","SET","value","2024-02-29"));c.set("pages",obj("action","SET","value",0));c.set("description",obj("action","SET","value",""));JsonNode p=preview(b,c);assertTrue(service.book(b,admin).path("book").get("pages").isNull());JsonNode r=confirm(p),v=r.path("books").get(0).path("publication");assertEquals(0,v.path("pages").asInt());assertEquals("",v.path("description").asText());assertEquals(1,v.path("revision").asLong());assertEquals(r,confirm(p));assertEquals(r,service.getByKey(p.path("operationKey").asText(),admin).get("receipt"));String text="合成📚原文\n第二行\t制表\r\n<script>原文</script> union select";JsonNode next=confirm(preview(b,set("description",text)));assertEquals(text,next.path("books").get(0).path("publication").path("description").asText());ObjectNode clear=changes().set("description",obj("action","CLEAR"));assertTrue(confirm(preview(b,clear)).path("books").get(0).path("publication").get("description").isNull());}
    @Test void descriptionsCountCodepointsAndRejectMalformedSurrogatesAndControlCharacters()throws Exception{long b=book();confirm(preview(b,set("description","📚".repeat(2000))));http(put("/books"),applicationJson.valueToTree(intake.read(b)),admin,200);assertEquals(1,service.book(b,admin).path("book").path("revision").asLong());for(String s:List.of("📚".repeat(2001),"bad\u0000","bad\u0001","bad\u007f","\ud800","\udc00"))reason("INVALID_INPUT",()->preview(b,set("description",s)));for(String s:List.of("\n","\r\n","\t","\u200d","  "))confirm(preview(b,set("description",s)));}
    @Test void strictDatesIntegersAndActionsRejectCoercion(){long b=book();for(Object x:List.of("2023-02-29","2024-02","2024","2024-2-01","0000-01-01","2024-04-31",20240101))reason("INVALID_INPUT",()->preview(b,set("publishDate",x)));for(Object x:List.of(-1,100000,1.0,"0",true))reason("INVALID_INPUT",()->preview(b,set("pages",x)));for(String s:List.of("0001-01-01","0999-12-31","9999-12-31"))confirm(preview(b,set("publishDate",s)));reason("INVALID_INPUT",()->preview(b,changes()));reason("INVALID_INPUT",()->preview(b,changes().set("pages",obj("action","CLEAR","value",null))));reason("INVALID_INPUT",()->preview(b,changes().set("description",obj("action","SET","value",null))));}
    @Test void strictUnknownMissingAndDuplicateJsonNeverWrite()throws Exception{long b=book();ObjectNode valid=input(entry(b,set("pages",0)));List<JsonNode> invalid=new ArrayList<>(List.of(NullNode.instance,tree(List.of()),valid.deepCopy().put("extra",1),valid.deepCopy().put("mode","SOURCE")));ObjectNode missing=valid.deepCopy();missing.remove("reason");invalid.add(missing);ObjectNode empty=valid.deepCopy();empty.set("entries",tree(List.of()));invalid.add(empty);for(JsonNode n:invalid)http(post("/catalog-publications/previews"),n,admin,400);String duplicate=write(valid).replace("\"mode\":\"MANUAL\"","\"mode\":\"MANUAL\",\"mode\":\"MANUAL\"");http(post("/catalog-publications/previews").contentType("application/json").content(duplicate),null,admin,400);http(post("/catalog-publications/previews").contentType("application/json").content(write(valid)+" {}"),null,admin,400);ObjectNode e=entry(b,set("pages",0));reason("INVALID_INPUT",()->service.preview(input(e,e),admin));assertTrue(service.book(b,admin).path("book").get("pages").isNull());}
    @Test void boundsOneToOneHundredAndCanonicalAscendingEntries(){List<JsonNode> entries=new ArrayList<>();for(int i=0;i<100;i++)entries.add(entry(book(),set("pages",i)));Collections.reverse(entries);ObjectNode n=input(entries.toArray(JsonNode[]::new));JsonNode p=service.preview(n,admin);long last=0;for(JsonNode b:p.path("preview").path("books")){assertTrue(b.path("bookId").asLong()>last);last=b.path("bookId").asLong();}Collections.reverse(entries);n.set("entries",tree(entries));assertEquals(p,service.preview(n,admin));entries.add(entry(book(),set("pages",0)));reason("INVALID_INPUT",()->service.preview(input(entries.toArray(JsonNode[]::new)),admin));assertEquals(100,confirm(p).path("books").size());}
    @Test void noOpDoesNotUpdateTimeRevisionOrCreateEvent(){long b=book();jdbc.update("UPDATE book SET pages=0,description='',update_time='2001-02-03 04:05:06' WHERE id=?",b);Map<String,Object> old=jdbc.queryForMap("SELECT * FROM book WHERE id=?",b);JsonNode p=preview(b,set("pages",0)),r=confirm(p);assertFalse(r.path("books").get(0).path("changed").asBoolean());assertTrue(r.path("books").get(0).get("eventId").isNull());assertEquals(old,jdbc.queryForMap("SELECT * FROM book WHERE id=?",b));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_publication_event WHERE book_id=?",Integer.class,b));}
    @Test void sameKeyDifferentActorOrInputIsConflictAndCommittedOriginalReplays(){long b=book();ObjectNode n=input(entry(b,set("pages",0)));JsonNode p=service.preview(n,admin),r=confirm(p);assertEquals(r,service.preview(n,admin).get("receipt"));ObjectNode changed=n.deepCopy().put("reason","不同说明");reason("IDEMPOTENCY_KEY_REUSED",()->service.preview(changed,admin));reason("IDEMPOTENCY_KEY_REUSED",()->service.preview(n,other));jdbc.update("UPDATE catalog_publication_request SET expires_at='2000-01-01' WHERE id=?",p.path("requestId").asLong());assertEquals(r,confirm(p));}
    @Test void expiryAndDigestRejectWithoutWrites(){long b=book();JsonNode p=preview(b,set("pages",0));reason("IDEMPOTENCY_KEY_REUSED",()->service.confirm(p.path("requestId").asLong(),obj("operationKey",p.get("operationKey"),"previewDigest","a".repeat(64)),admin));jdbc.update("UPDATE catalog_publication_request SET expires_at='2000-01-01' WHERE id=?",p.path("requestId").asLong());reason("PREVIEW_EXPIRED",()->confirm(p));assertEquals(0,service.book(b,admin).path("book").path("revision").asLong());}
    protected void metadata(long b,String field,Object value){InventoryIntakeContracts.MetadataUpdate n=new InventoryIntakeContracts.MetadataUpdate();n.setExpectedMetadataDigest(intake.view(b).metadataDigest());n.setChanges(obj(field,value));intake.update(b,n);}
    @Test void legacyMetadataAbaAuditsAndInvalidatesPreview(){long b=book();JsonNode p=preview(b,set("pages",0));metadata(b,"description","A");metadata(b,"description",null);reason("PUBLICATION_CHANGED",()->confirm(p));assertEquals(2,service.book(b,admin).path("book").path("revision").asLong());assertEquals(2,service.events(b,1,20,admin).path("total").asLong());assertEquals(0,service.events(b,1,20,clerk).path("total").asLong());}
    @Test void legacyNormalizeSingleAndBatchAndIsbnAbaAreGuarded()throws Exception{long b=book();String title=intake.read(b).getTitle();JsonNode p=preview(b,set("pages",0));http(put("/book-normalize/"+b),obj("title","修改合成"),admin,200);http(put("/book-normalize/batch"),tree(List.of(obj("id",b,"title",title))),admin,200);reason("PUBLICATION_CHANGED",()->confirm(p));JsonNode next=preview(b,set("pages",0));String isbn=intake.read(b).getIsbn();metadata(b,"isbn","ABA123");metadata(b,"isbn",isbn);reason("PUBLICATION_CHANGED",()->confirm(next));assertEquals(4,service.events(b,1,20,admin).path("total").asLong());}
    @Test void fullPutAndMetadataKeepLegalMultilineAndDoNotMiscountNoOp()throws Exception{long b=book();String text="原行\n第二行\t合成📚<script>原文</script> union select";ObjectNode changes=set("description",text);changes.set("pages",obj("action","SET","value",0));confirm(preview(b,changes));Map<String,Object> old=jdbc.queryForMap("SELECT * FROM book WHERE id=?",b);metadata(b,"description",text);assertEquals(1,service.book(b,admin).path("book").path("revision").asInt());JsonNode dto=applicationJson.valueToTree(intake.read(b));http(put("/books"),dto,admin,200);assertEquals(text,intake.read(b).getDescription());assertEquals(1,service.book(b,admin).path("book").path("revision").asInt());assertEquals(1,service.events(b,1,20,admin).path("total").asInt());http(put("/books"),((ObjectNode)dto.deepCopy()).put("pages",-1),admin,400);assertFalse(dto.has("publicationRevision"));assertEquals(old.get("pages"),intake.read(b).getPages());}
    @Test void displayOverrideDoesNotChangeDigestOrInvalidatePreview(){long b=book();JsonNode p=preview(b,set("pages",0));String digest=service.book(b,admin).path("book").path("metadataDigest").asText();jdbc.update("INSERT INTO catalog_book_attribute(book_id,revision,display_title_override,display_origin,updated_at) VALUES (?,1,'合成展示覆盖','MANUAL',CURRENT_TIMESTAMP)",b);assertEquals(digest,service.book(b,admin).path("book").path("metadataDigest").asText());assertEquals("合成展示覆盖",confirm(p).path("books").get(0).path("publication").path("displayTitle").asText());}
    @Test void unrelatedOldBusinessColumnsAndAllFrozenJsonRemainByteExact(){long b=book();jdbc.update("INSERT INTO book_copy(book_id,barcode,action_version) VALUES (?, ?,7)",b,"000Aa📚"+b);Map<String,Object> old=jdbc.queryForMap("SELECT * FROM book WHERE id=?",b);old.keySet().removeAll(Set.of("publish_date","pages","description","update_time","publication_revision"));List<Map<String,Object>> copies=jdbc.queryForList("SELECT * FROM book_copy WHERE book_id=?",b);Map<String,Long> counts=new TreeMap<>();for(String table:List.of("borrow_record","stock_flow","catalog_attribute_event","catalog_identity_event","inventory_intake_request","book_copy_action_request"))counts.put(table,jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Long.class));confirm(preview(b,set("description","新增合成简介")));Map<String,Object> after=jdbc.queryForMap("SELECT * FROM book WHERE id=?",b);after.keySet().removeAll(Set.of("publish_date","pages","description","update_time","publication_revision"));assertEquals(old,after);assertEquals(hash(copies),hash(jdbc.queryForList("SELECT * FROM book_copy WHERE book_id=?",b)));counts.forEach((table,count)->assertEquals(count,jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Long.class),table));}
    protected boolean mysql(){try(var c=jdbc.getDataSource().getConnection()){return c.getMetaData().getDatabaseProductName().equals("MySQL");}catch(Exception e){throw new RuntimeException(e);}}
    @Test void auditFailureOnSecondBookRollsBackEntireBatchAndOriginalRetrySucceeds(){long a=book(),b=book();JsonNode p=service.preview(input(entry(a,set("pages",0)),entry(b,set("pages",1))),admin);String ck="ck_synthetic_b36_"+b;jdbc.execute("ALTER TABLE catalog_publication_event ADD CONSTRAINT "+ck+" CHECK(book_id<>"+b+")");try{reason("PUBLICATION_SAVE_FAILED",()->confirm(p));assertEquals(0,service.book(a,admin).path("book").path("revision").asLong());assertTrue(intake.read(a).getPages()==null);assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_publication_event WHERE book_id IN (?,?)",Integer.class,a,b));assertEquals("PREVIEWED",service.getRequest(p.path("requestId").asLong(),admin).path("state").asText());}finally{jdbc.execute("ALTER TABLE catalog_publication_event DROP "+(mysql()?"CHECK ":"CONSTRAINT ")+ck);}assertEquals(2,confirm(p).path("books").size());}
    @Test void secondBookVersionConflictRollsBackEarlierBook(){long a=book(),b=book();JsonNode p=service.preview(input(entry(a,set("pages",0)),entry(b,set("pages",1))),admin);metadata(b,"pages",9);reason("PUBLICATION_CHANGED",()->confirm(p));assertNull(intake.read(a).getPages());assertEquals(0,service.book(a,admin).path("book").path("revision").asLong());}
    @Test void maxRevisionAllowsNoOpButRejectsActualMutationAndNegativeCheck(){long b=book();jdbc.update("UPDATE book SET publication_revision=?,pages=0 WHERE id=?",Long.MAX_VALUE,b);assertFalse(confirm(preview(b,set("pages",0))).path("books").get(0).path("changed").asBoolean());reason("PUBLICATION_CHANGED",()->preview(b,set("pages",1)));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("UPDATE book SET publication_revision=-1 WHERE id=?",b));reason("PUBLICATION_CHANGED",()->metadata(b,"pages",1));assertEquals(0,intake.read(b).getPages());}
    @Test void logicalDeletionAppendsVersionAndAudit(){long b=book();JsonNode preview=preview(b,set("pages",0));books.delete(b);reason("PUBLICATION_CHANGED",()->confirm(preview));assertEquals(1,jdbc.queryForObject("SELECT publication_revision FROM book WHERE id=?",Long.class,b));assertEquals("LEGACY_DELETE",jdbc.queryForObject("SELECT kind FROM catalog_publication_event WHERE book_id=?",String.class,b));assertEquals(1,service.events(b,1,20,admin).path("total").asInt());reason("BOOK_NOT_FOUND",()->service.book(b,admin));}
    @Test void demotedAdministratorCannotReadReplayOrConfirmBulkEvenAfterCommit(){long a=book(),b=book();ObjectNode input=input(entry(a,set("pages",0)),entry(b,set("pages",0)));JsonNode p=service.preview(input,admin);var demoted=new PublicationSupport.Actor(admin.id(),false,true);JsonNode confirm=obj("operationKey",p.get("operationKey"),"previewDigest",p.get("previewDigest"));reason("CATALOG_PUBLICATION_ROLE_REQUIRED",()->service.getRequest(p.path("requestId").asLong(),demoted));reason("CATALOG_PUBLICATION_ROLE_REQUIRED",()->service.getByKey(p.path("operationKey").asText(),demoted));reason("CATALOG_PUBLICATION_ROLE_REQUIRED",()->service.preview(input,demoted));reason("CATALOG_PUBLICATION_ROLE_REQUIRED",()->service.confirm(p.path("requestId").asLong(),confirm,demoted));confirm(p);reason("CATALOG_PUBLICATION_ROLE_REQUIRED",()->service.getRequest(p.path("requestId").asLong(),demoted));reason("CATALOG_PUBLICATION_ROLE_REQUIRED",()->service.getByKey(p.path("operationKey").asText(),demoted));reason("CATALOG_PUBLICATION_ROLE_REQUIRED",()->service.preview(input,demoted));reason("CATALOG_PUBLICATION_ROLE_REQUIRED",()->service.confirm(p.path("requestId").asLong(),confirm,demoted));reason("OWNER_REQUIRED",()->service.confirm(p.path("requestId").asLong(),confirm,other));}
    @Test void receiptSaveFailureRollsBackAllBooksAndEvents(){long a=book(),b=book();JsonNode p=service.preview(input(entry(a,set("pages",0)),entry(b,set("pages",0))),admin);long request=p.path("requestId").asLong();String ck="ck_synthetic_b36_receipt_"+request;jdbc.execute("ALTER TABLE catalog_publication_request ADD CONSTRAINT "+ck+" CHECK(operation_key<>X'"+HexFormat.of().formatHex(bytes(p.path("operationKey").asText()))+"' OR state<>'COMMITTED')");try{reason("PUBLICATION_SAVE_FAILED",()->confirm(p));for(long book:List.of(a,b)){assertNull(intake.read(book).getPages());assertEquals(0,service.book(book,admin).path("book").path("revision").asLong());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_publication_event WHERE book_id=?",Integer.class,book));}assertEquals("PREVIEWED",service.getRequest(request,admin).path("state").asText());}finally{jdbc.execute("ALTER TABLE catalog_publication_request DROP "+(mysql()?"CHECK ":"CONSTRAINT ")+ck);}confirm(p);}
    @Test void concurrentOriginalKeyAndConfirmProduceOneRequestAndEvent()throws Exception{long b=book();ObjectNode n=input(entry(b,set("pages",0)));ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<JsonNode> x=pool.submit(()->service.preview(n,admin)),y=pool.submit(()->service.preview(n,admin));JsonNode p=x.get(20,TimeUnit.SECONDS);assertEquals(p,y.get(20,TimeUnit.SECONDS));Future<JsonNode> first=pool.submit(()->confirm(p)),second=pool.submit(()->confirm(p));assertEquals(first.get(20,TimeUnit.SECONDS),second.get(20,TimeUnit.SECONDS));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM catalog_publication_event WHERE book_id=?",Integer.class,b));}finally{pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}}
    @Test void syntheticHttpFixtureAndSafeOwnEventsExport()throws Exception{long a=book(),b=book();ObjectNode ca=set("pages",0);ca.set("publishDate",obj("action","SET","value","2024-02-29"));ca.set("description",obj("action","SET","value","合成简介\n第二行\t📚"));ObjectNode n=input(entry(b,set("description","")),entry(a,ca));JsonNode read=http(get("/catalog-publications/books/"+a),null,admin,200),preview=http(post("/catalog-publications/previews"),n,admin,200),p=preview.path("data"),confirmInput=obj("operationKey",p.get("operationKey"),"previewDigest",p.get("previewDigest"));JsonNode receipt=http(post("/catalog-publications/"+p.path("requestId").asLong()+"/confirm"),confirmInput,admin,200),events=http(get("/catalog-publications/books/"+a+"/events"),null,admin,200),otherEvents=http(get("/catalog-publications/books/"+a+"/events"),null,other,200);assertEquals(0,otherEvents.path("data").path("total").asLong());http(get("/catalog-publications/books/"+a+"/events?size=101"),null,admin,400);String dir=System.getProperty("b36.evidence.dir");if(dir!=null){Path path=Path.of(dir);Files.createDirectories(path);Files.writeString(path.resolve(mysql()?"synthetic-http-mysql.json":"synthetic-http-h2.json"),JSON.writerWithDefaultPrettyPrinter().writeValueAsString(obj("synthetic",true,"transport","Spring MVC real controller/filter/service/database","read",read,"previewInput",n,"preview",preview,"confirmInput",confirmInput,"receipt",receipt,"events",events,"otherActorEvents",otherEvents)));}}
}
